    35→async function applyImmersiveMode(bg: string, isDark: boolean) {
    36→  if (Platform.OS !== 'android') return;
    37→  try {
    38→    const sdkVersion = Platform.Version as number;
    39→    if (sdkVersion < 30) {
    40→      await NavigationBar.setVisibilityAsync('visible');
    41→    }
    42→    await NavigationBar.setButtonStyleAsync(isDark ? 'light' : 'dark');
    43→    if (sdkVersion < 35) {
    44→      await NavigationBar.setBackgroundColorAsync(bg);
    45→      await NavigationBar.setBehaviorAsync('inset-swipe');
    46→    }
    47→  } catch {}
    48→}
